// 创建顶事件
CREATE (te1:TopEvent {
  id: "TE-1", 
  name: "集群完全不可用", 
  severity: "P0",
  slo: "可用性 < 100%"
})

// 创建中间事件
CREATE (ie11:IntermediateEvent {
  id: "IE-1.1", 
  name: "控制平面问题",
  gate_type: "OR"
})

// 创建底事件
CREATE (be11:BasicEvent {
  id: "BE-1.1", 
  name: "API Server问题",
  probability: 0.001,
  mttr_minutes: 30,
  observable: true,
  metric: "up{job='kubernetes-apiservers'}"
})

CREATE (be12:BasicEvent {
  id: "BE-1.2", 
  name: "etcd集群问题",
  probability: 0.0005,
  mttr_minutes: 60,
  observable: true,
  metric: "etcd_server_has_leader"
})

// 创建关系
CREATE (te1)-[:HAS_CHILD {gate: "OR"}]->(ie11)
CREATE (ie11)-[:HAS_CHILD {gate: "OR"}]->(be11)
CREATE (ie11)-[:HAS_CHILD {gate: "OR"}]->(be12)

// 查询: 找到所有导致 TE-1 的最短路径
MATCH path = (te:TopEvent {id: "TE-1"})-[:HAS_CHILD*]->(be:BasicEvent)
RETURN path
ORDER BY length(path)

// 查询: 找到所有 1 阶最小割集(单点问题)
MATCH (te:TopEvent)-[:HAS_CHILD {gate: "OR"}]->(be:BasicEvent)
RETURN be.id, be.name, be.probability
ORDER BY be.probability DESC

class FTADrivenAgent:
    """基于 FTA 知识图谱的智能诊断 Agent"""

    def __init__(self, fta_graph, k8s_client, metrics_client):
        self.fta = fta_graph           # FTA 知识图谱 (Neo4j)
        self.k8s = k8s_client          # Kubernetes API 客户端
        self.metrics = metrics_client  # Prometheus 客户端
        self.history = []              # 诊断历史

    def handle_alert(self, alert):
        """处理告警/工单的入口"""
        # 1. 将告警映射到 FTA 顶事件
        top_event = self.map_alert_to_top_event(alert)

        # 2. 执行故障树遍历诊断
        diagnosis = self.diagnose(top_event)

        # 3. 执行修复
        if diagnosis.auto_healable:
            result = self.heal(diagnosis)
        else:
            result = self.escalate_to_human(diagnosis)

        # 4. 学习反馈
        self.learn(alert, diagnosis, result)

        return result

    def diagnose(self, event):
        """递归遍历故障树进行诊断"""
        if event.is_basic_event():
            # 底事件: 直接检查可观测数据
            status = self.check_observable(event)
            return DiagnosisResult(event, status)

        children = self.fta.get_children(event)
        gate_type = self.fta.get_gate_type(event)

        if gate_type == "OR":
            # OR 门: 按概率排序，并行检查
            sorted_children = sorted(children, 
                                     key=lambda c: c.probability, 
                                     reverse=True)
            results = parallel_execute(
                [lambda c=c: self.diagnose(c) for c in sorted_children]
            )
            # 返回第一个确认问题的路径
            for r in results:
                if r.is_faulty:
                    return r

        elif gate_type == "AND":
            # AND 门: 顺序检查，任一正常即排除
            for child in children:
                result = self.diagnose(child)
                if not result.is_faulty:
                    return DiagnosisResult(event, healthy=True)
            # 所有子事件都问题
            return DiagnosisResult(event, is_faulty=True, 
                                   children=children)

        elif gate_type.startswith("VOTING"):
            # k/n 投票门
            k = gate_type.k
            results = parallel_execute(
                [lambda c=c: self.diagnose(c) for c in children]
            )
            faulty_count = sum(1 for r in results if r.is_faulty)
            return DiagnosisResult(event, 
                                   is_faulty=(faulty_count >= k))

    def check_observable(self, basic_event):
        """检查底事件的可观测数据"""
        for metric in basic_event.metrics:
            value = self.metrics.query(metric.expression)
            if metric.evaluate(value):
                return FaultyStatus(
                    event=basic_event,
                    evidence=f"{metric.expression} = {value}",
                    confidence=0.9
                )

        for log_pattern in basic_event.log_patterns:
            matches = self.k8s.search_logs(log_pattern)
            if matches:
                return FaultyStatus(
                    event=basic_event,
                    evidence=f"日志匹配: {log_pattern}",
                    confidence=0.85
                )

        return HealthyStatus(event=basic_event)

    def heal(self, diagnosis):
        """执行修复动作"""
        actions = self.fta.get_healing_actions(diagnosis.root_cause)

        for action in sorted(actions, key=lambda a: a.success_rate, 
                             reverse=True):
            if action.risk_level == "high":
                # 高风险操作需要人工确认
                approval = self.request_human_approval(action)
                if not approval:
                    continue

            # 执行修复
            result = action.execute(self.k8s)

            # 验证恢复
            if self.verify_recovery(diagnosis.top_event):
                return HealingResult(success=True, action=action)

        return HealingResult(success=False, 
                             reason="所有修复方案均未生效")

    def learn(self, alert, diagnosis, result):
        """从问题中学习，更新 FTA"""
        record = {
            "timestamp": now(),
            "alert": alert,
            "diagnosis_path": diagnosis.path,
            "root_cause": diagnosis.root_cause,
            "healing_action": result.action,
            "success": result.success,
            "mttr": result.duration
        }
        self.history.append(record)

        # 更新概率数据
        self.fta.update_probability(
            diagnosis.root_cause, 
            increment=1
        )

        # 检测是否有新的故障模式
        if not diagnosis.path_exists_in_fta:
            self.fta.propose_new_path(
                diagnosis.path,
                requires_human_review=True
            )

def generate_runbook_from_fta(top_event_id, fta_graph):
    """
    从 FTA 知识图谱自动生成结构化 Runbook

    Args:
        top_event_id: 顶事件 ID (如 "TE-1")
        fta_graph: FTA 知识图谱 (Neo4j 连接)

    Returns:
        Runbook YAML 结构
    """
    top_event = fta_graph.get_event(top_event_id)

    runbook = {
        "apiVersion": "troubleshooting.kudig.io/v1",
        "kind": "Runbook",
        "metadata": {
            "name": f"auto-runbook-{top_event_id.lower()}",
            "labels": {
                "fta-top-event": top_event_id,
                "severity": top_event.severity,
                "auto-generated": "true"
            }
        },
        "spec": {
            "trigger": {
                "alerts": top_event.mapped_alerts,
                "severity": top_event.severity
            },
            "diagnosis": [],
            "healing": []
        }
    }

    # 递归遍历故障树，生成诊断步骤
    step_counter = [0]

    def traverse(event, depth=0):
        if event.is_basic_event():
            step_counter[0] += 1
            step = {
                "step": step_counter[0],
                "fta_event": event.id,
                "description": event.name,
                "depth": depth,
                "commands": event.diagnosis_commands,
                "conditions": []
            }

            # 添加条件判断
            if event.is_faulty_condition:
                step["conditions"].append({
                    "if": event.is_faulty_condition,
                    "action": "flag_as_root_cause",
                    "healing_actions": [
                        a.to_dict() for a in event.healing_actions
                    ]
                })

            runbook["spec"]["diagnosis"].append(step)
            return

        children = fta_graph.get_children(event)
        gate_type = fta_graph.get_gate_type(event)

        # 记录逻辑门信息
        step_counter[0] += 1
        gate_step = {
            "step": step_counter[0],
            "fta_event": event.id,
            "description": f"[{gate_type}门] {event.name}",
            "gate_type": gate_type,
            "execution_mode": "parallel" if gate_type == "OR" else "sequential"
        }
        runbook["spec"]["diagnosis"].append(gate_step)

        # 按概率排序（OR门高概率优先）
        if gate_type == "OR":
            children.sort(key=lambda c: c.probability, reverse=True)

        for child in children:
            traverse(child, depth + 1)

    traverse(top_event)
    return runbook

class FTAInferenceEngine:
    """FTA 推理引擎 - 将告警映射到根因"""

    def __init__(self, graph_db):
        self.graph = graph_db  # Neo4j

    def infer(self, alerts, metrics_snapshot, logs_snapshot):
        """
        输入: 告警列表 + 当前指标快照 + 日志快照
        输出: 根因列表 (按概率排序)
        """
        # 1. 告警聚合 - 将多个告警归并到顶事件
        top_events = self.aggregate_alerts_to_top_events(alerts)

        # 2. 对每个顶事件执行 FTA 遍历
        all_root_causes = []
        for te in top_events:
            candidates = self.traverse_fault_tree(
                te, metrics_snapshot, logs_snapshot
            )
            all_root_causes.extend(candidates)

        # 3. 概率排序
        ranked = self.rank_by_probability(all_root_causes)

        # 4. 去重 (同一根因可能通过不同路径到达)
        deduped = self.deduplicate(ranked)

        return deduped

    def traverse_fault_tree(self, event, metrics, logs):
        """深度优先遍历故障树"""
        if event.is_basic_event():
            # 检查底事件是否实际发生
            evidence = self.check_evidence(event, metrics, logs)
            if evidence.is_confirmed:
                return [RootCause(
                    event=event,
                    confidence=evidence.confidence,
                    evidence=evidence.details
                )]
            return []

        children = self.graph.get_children(event)
        gate = self.graph.get_gate_type(event)

        results = []

        if gate == "OR":
            # OR 门: 探索所有分支，收集所有确认的根因
            for child in sorted(children, 
                               key=lambda c: c.prior_probability,
                               reverse=True):
                child_results = self.traverse_fault_tree(
                    child, metrics, logs
                )
                results.extend(child_results)

        elif gate == "AND":
            # AND 门: 所有子事件都确认才返回
            all_confirmed = True
            and_evidences = []
            for child in children:
                child_results = self.traverse_fault_tree(
                    child, metrics, logs
                )
                if not child_results:
                    all_confirmed = False
                    break
                and_evidences.extend(child_results)
            if all_confirmed:
                results.extend(and_evidences)

        return results

    def check_evidence(self, basic_event, metrics, logs):
        """检查底事件的证据"""
        confidence = 0.0
        details = []

        # 检查指标
        for metric_rule in basic_event.metric_rules:
            value = metrics.query(metric_rule.expression)
            if metric_rule.evaluate(value):
                confidence = max(confidence, 0.9)
                details.append(f"指标确认: {metric_rule.expression} = {value}")

        # 检查日志
        for log_pattern in basic_event.log_patterns:
            matches = logs.search(log_pattern)
            if matches:
                confidence = max(confidence, 0.85)
                details.append(f"日志确认: 匹配 '{log_pattern}' ({len(matches)}条)")

        # 检查 K8s Events
        for event_pattern in basic_event.k8s_events:
            events = self.k8s.get_events(event_pattern)
            if events:
                confidence = max(confidence, 0.80)
                details.append(f"事件确认: {event_pattern} ({len(events)}条)")

        return Evidence(
            is_confirmed=(confidence > 0.5),
            confidence=confidence,
            details=details
        )
